primaryQuery:
run: order_items extend {
  join_one: inventory_items is inventory_items
    on inventory_item_id = inventory_items.id
} -> {
  aggregate: products_sold is count(inventory_items.product_id)
}

verifyQuery:
run: inventory_items extend {
  join_one: oi is order_items on id = oi.inventory_item_id
} -> {
  where: oi.id is not null
  group_by: product_id
} -> { aggregate: products_sold is count() }
